using EmployeeAttendanceSystem.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace EmployeeAttendanceSystem.Controllers;
[ApiController][Authorize(Roles="HR")][Route("api/hr")]
public class HrController:ControllerBase{readonly AppDbContext db;public HrController(AppDbContext db){this.db=db;}[HttpGet("dashboard")]public IActionResult Dashboard(){var t=DateTime.Now.Date;var a=db.Attendances.Where(x=>x.Date==t).ToList();var total=db.Users.Count(x=>x.Role=="Employee");var present=a.Count(x=>x.Status=="Present"||x.Status=="Late"||x.Status=="Half Day");var leave=db.LeaveRequests.Where(x=>x.Status=="Approved"&&x.StartDate<=t&&x.EndDate>=t).Select(x=>x.UserId).Distinct().Count();return Ok(new{totalEmployees=total,presentToday=present,absentToday=Math.Max(0,total-present-leave),onLeaveToday=leave});}[HttpGet("employees")]public IActionResult Employees()=>Ok(db.Users.Where(x=>x.Role=="Employee").Select(x=>new{x.Id,x.Name,x.Email,x.IsActive,x.CreatedAt}).ToList());[HttpGet("attendance")]public IActionResult Attendance(DateTime? date){var d=(date??DateTime.Now).Date;return Ok(db.Attendances.Include(x=>x.User).Where(x=>x.Date==d).Select(x=>new{x.Id,employee=x.User!.Name,x.Date,x.CheckIn,x.CheckOut,x.WorkingHours,x.Status}).ToList());}}
